css:
[data-bz-section="pg-banner"] .bz-block { padding-block: 0; }
[data-bz-section="pg-banner"] .bz-block p { margin: 0; }
[data-bz-section="pg-banner"] .bz-section::before { content: ""; position: absolute; inset: 0; z-index: 1; background: linear-gradient(100deg, rgba(10, 11, 14, 0.92) 30%, rgba(10, 11, 14, 0.5) 75%); pointer-events: none; }
[data-bz-section="pg-banner"] .bz-block--image { position: absolute; inset: 0; z-index: 0; }
[data-bz-section="pg-banner"] .bz-block--image :is(.bz-container, .bz-figure, img) { display: block; width: 100%; height: 100%; }
[data-bz-section="pg-banner"] .bz-block--image img { object-fit: cover; border-radius: 0; }
[data-bz-section="pg-banner"] .bz-row { position: relative; z-index: 2; width: 100%; }
[data-bz-section="pg-banner"] [data-bz-node="pb-crumb"] p { font-size: 13px; line-height: normal; color: #c9cbd0; margin-bottom: 20px; }
[data-bz-section="pg-banner"] [data-bz-node="pb-crumb"] a { color: inherit; text-decoration: none; }
[data-bz-section="pg-banner"] [data-bz-node="pb-crumb"] strong { font-weight: 400; color: var(--card); }
[data-bz-section="pg-banner"] .bz-eyebrow { color: var(--accent-soft); margin-bottom: 14px; }
[data-bz-section="pg-banner"] [data-bz-node="pb-h"] h1 { font-size: 44px; line-height: 1.15; margin: 0 0 20px; color: var(--card); max-width: 680px; }
[data-bz-section="pg-banner"] [data-bz-node="pb-sub"] h2 { font-size: 20px; font-weight: 600; line-height: normal; margin: 0 0 20px; color: var(--accent-soft); }
[data-bz-section="pg-banner"] [data-bz-node="pb-tag"] p { font-size: 17px; line-height: 1.6; color: #c9cbd0; max-width: 620px; }
@media (max-width: 640px) { [data-bz-section="pg-banner"] [data-bz-node="pb-h"] h1 { font-size: 32px; } }
